// ============================================================
// AI SKILL GAP ANALYZER
// n8n Code Node
// Mode: Run Once for All Items
// ============================================================


// ============================================================
// 1. JOB REQUIREMENTS
// ============================================================

const jobRequirements = {

  "python developer": {
    "Python": 10,
    "OOP": 8,
    "DSA": 7,
    "SQL": 8,
    "REST API": 8,
    "Git": 6,
    "Django": 9,
    "FastAPI": 7,
    "PostgreSQL": 7,
    "Testing": 6,
    "Docker": 5,
    "Linux": 5
  },

  "full stack developer": {
    "HTML": 7,
    "CSS": 7,
    "JavaScript": 10,
    "React": 8,
    "Node.js": 8,
    "REST API": 8,
    "SQL": 8,
    "Git": 6,
    "Authentication": 6,
    "Responsive Design": 6,
    "Testing": 5,
    "Docker": 4
  },

  "machine learning engineer": {
    "Python": 10,
    "NumPy": 7,
    "Pandas": 7,
    "Scikit-Learn": 9,
    "Statistics": 8,
    "Machine Learning": 10,
    "Data Preprocessing": 8,
    "Feature Engineering": 8,
    "Model Evaluation": 8,
    "SQL": 6,
    "Git": 5,
    "FastAPI": 5,
    "Docker": 5
  },

  "ai/ml engineer": {
    "Python": 10,
    "NumPy": 7,
    "Pandas": 7,
    "Machine Learning": 10,
    "Deep Learning": 9,
    "Scikit-Learn": 8,
    "TensorFlow": 7,
    "PyTorch": 7,
    "NLP": 7,
    "LLM": 8,
    "REST API": 6,
    "Git": 5,
    "Docker": 5
  },

  "php developer": {
    "PHP": 10,
    "OOP": 8,
    "MySQL": 8,
    "SQL": 7,
    "HTML": 6,
    "CSS": 6,
    "JavaScript": 8,
    "REST API": 7,
    "Git": 6,
    "Laravel": 9,
    "Authentication": 6,
    "Testing": 5
  }

};


// ============================================================
// 2. HELPER FUNCTIONS
// ============================================================

function normalize(text) {

  return String(text || "")
    .toLowerCase()
    .trim()
    .replace(/[._-]/g, " ")
    .replace(/\s+/g, " ");

}


function getLevel(level) {

  if (typeof level === "number") {

    return Math.max(
      0,
      Math.min(5, level)
    );

  }

  const value = normalize(level);

  if (value.includes("expert")) return 5;

  if (value.includes("advanced")) return 4;

  if (value.includes("intermediate")) return 3;

  if (value.includes("basic")) return 2;

  if (value.includes("beginner")) return 1;

  if (
    value.includes("missing") ||
    value.includes("none") ||
    value.includes("no knowledge")
  ) {
    return 0;
  }

  return 0;

}


function escapeHTML(value) {

  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");

}


function getLevelLabel(level) {

  switch (level) {

    case 0:
      return "Missing";

    case 1:
      return "Beginner";

    case 2:
      return "Basic";

    case 3:
      return "Intermediate";

    case 4:
      return "Advanced";

    case 5:
      return "Expert";

    default:
      return "Unknown";

  }

}


function getStatusClass(status) {

  if (status === "Strong") {
    return "strong";
  }

  if (status === "Partial") {
    return "partial";
  }

  return "missing";

}


// ============================================================
// 3. GET INPUT
// ============================================================

const input = items[0]?.json || {};


// ============================================================
// 4. TARGET JOB ROLE
// ============================================================

const targetRole =
  input.targetRole ||
  input.target_role ||
  input.jobRole ||
  input.job_role ||
  "Python Developer";


// ============================================================
// 5. FIND JOB ROLE
// ============================================================

const roleKey = Object.keys(jobRequirements).find(

  key =>
    normalize(key) ===
    normalize(targetRole)

);


if (!roleKey) {

  return [

    {

      json: {

        success: false,

        error:
          "Target job role is not supported.",

        receivedRole:
          targetRole,

        availableRoles:
          Object.keys(jobRequirements)

      }

    }

  ];

}


// ============================================================
// 6. GET AI-GENERATED SKILLS
// ============================================================

let candidateSkills =
  input.skills || [];


// If skills are returned as a JSON string
if (
  typeof candidateSkills === "string"
) {

  try {

    candidateSkills =
      JSON.parse(candidateSkills);

  }

  catch (error) {

    candidateSkills = [];

  }

}


// Safety check
if (!Array.isArray(candidateSkills)) {

  candidateSkills = [];

}


// ============================================================
// 7. CREATE CANDIDATE SKILL MAP
// ============================================================

const skillMap = {};


for (const skill of candidateSkills) {

  if (!skill) {
    continue;
  }


  const name =
    skill.name ||
    skill.skill ||
    skill.title;


  if (!name) {
    continue;
  }


  const level = getLevel(

    skill.level ??
    skill.proficiency ??
    skill.currentLevel ??
    0

  );


  skillMap[normalize(name)] = {

    name: String(name),

    level

  };

}


// ============================================================
// 8. GET JOB REQUIREMENTS
// ============================================================

const requirements =
  jobRequirements[roleKey];


// ============================================================
// 9. INITIALIZE SCORE
// ============================================================

let totalWeight = 0;

let earnedWeight = 0;


const comparison = [];

const strongSkills = [];

const partialSkills = [];

const missingSkills = [];


// ============================================================
// 10. COMPARE SKILLS
// ============================================================

for (
  const [requiredSkill, weight]
  of Object.entries(requirements)
) {

  totalWeight += weight;


  const normalizedRequired =
    normalize(requiredSkill);


  let candidate =
    skillMap[normalizedRequired];


  // --------------------------------------------------------
  // Partial name matching
  // --------------------------------------------------------

  if (!candidate) {

    const matchingKey =
      Object.keys(skillMap).find(

        key =>

          key.includes(
            normalizedRequired
          ) ||

          normalizedRequired.includes(
            key
          )

      );


    if (matchingKey) {

      candidate =
        skillMap[matchingKey];

    }

  }


  // --------------------------------------------------------
  // Current level
  // --------------------------------------------------------

  const currentLevel =
    candidate
      ? candidate.level
      : 0;


  // --------------------------------------------------------
  // Calculate weighted score
  // --------------------------------------------------------

  const skillScore =
    (currentLevel / 5) *
    weight;


  earnedWeight +=
    skillScore;


  // --------------------------------------------------------
  // Determine status
  // --------------------------------------------------------

  let status;


  if (currentLevel >= 4) {

    status = "Strong";

    strongSkills.push(
      requiredSkill
    );

  }

  else if (currentLevel > 0) {

    status = "Partial";

    partialSkills.push(
      requiredSkill
    );

  }

  else {

    status = "Missing";

    missingSkills.push(
      requiredSkill
    );

  }


  // --------------------------------------------------------
  // Add comparison
  // --------------------------------------------------------

  comparison.push({

    skill:
      requiredSkill,

    importance:
      weight,

    currentLevel,

    currentLevelLabel:
      getLevelLabel(
        currentLevel
      ),

    score:
      Number(
        skillScore.toFixed(2)
      ),

    status

  });

}


// ============================================================
// 11. FINAL SCORE
// ============================================================

let score = 0;


if (totalWeight > 0) {

  score =
    Number(

      (
        (earnedWeight /
          totalWeight) *
        100

      ).toFixed(1)

    );

}


// Make sure score is between 0 and 100
score =
  Math.max(
    0,
    Math.min(
      100,
      score
    )
  );


// ============================================================
// 12. JOB READINESS
// ============================================================

let jobReadiness;


if (score >= 85) {

  jobReadiness =
    "Strong Candidate";

}

else if (score >= 70) {

  jobReadiness =
    "Job Ready";

}

else if (score >= 55) {

  jobReadiness =
    "Almost Job Ready";

}

else if (score >= 35) {

  jobReadiness =
    "Beginner / Building";

}

else {

  jobReadiness =
    "Not Ready";

}


// ============================================================
// 13. SCORE MESSAGE
// ============================================================

let scoreMessage;


if (score >= 85) {

  scoreMessage =
    "Excellent match. Focus on interview preparation and advanced practical projects.";

}

else if (score >= 70) {

  scoreMessage =
    "Good match. Strengthen the remaining gaps and build practical projects.";

}

else if (score >= 55) {

  scoreMessage =
    "You are close to being job ready. Focus on the high-priority missing skills.";

}

else if (score >= 35) {

  scoreMessage =
    "You have a foundation but need more practical learning before becoming job ready.";

}

else {

  scoreMessage =
    "Focus on the fundamental skills required for this role.";

}


// ============================================================
// 14. PRIORITY GAPS
// ============================================================

const priorityGaps = comparison

  .filter(
    item =>
      item.status !== "Strong"
  )

  .sort(

    (a, b) => {

      // Missing skills first

      if (
        a.status === "Missing" &&
        b.status !== "Missing"
      ) {

        return -1;

      }


      if (
        b.status === "Missing" &&
        a.status !== "Missing"
      ) {

        return 1;

      }


      // Higher importance first

      return (
        b.importance -
        a.importance
      );

    }

  );


// ============================================================
// 15. LEARNING PRIORITIES
// ============================================================

const highPriority =
  priorityGaps

    .filter(
      item =>
        item.importance >= 8
    )

    .map(
      item =>
        item.skill
    );


const mediumPriority =
  priorityGaps

    .filter(
      item =>
        item.importance >= 6 &&
        item.importance < 8
    )

    .map(
      item =>
        item.skill
    );


const lowPriority =
  priorityGaps

    .filter(
      item =>
        item.importance < 6
    )

    .map(
      item =>
        item.skill
    );


// ============================================================
// 16. 30 / 60 / 90 DAY ROADMAP
// ============================================================

const roadmap = {

  "30_Days":
    highPriority.slice(
      0,
      4
    ),

  "60_Days": [

    ...highPriority.slice(4),

    ...mediumPriority.slice(
      0,
      4
    )

  ],

  "90_Days": [

    ...mediumPriority.slice(4),

    ...lowPriority

  ]

};


// ============================================================
// 17. HTML - SKILL TABLE
// ============================================================

const skillRows =
  comparison

    .map(item => {

      const percentage =
        Math.round(
          (item.currentLevel /
            5) *
          100
        );


      return `

        <tr>

          <td>
            <strong>
              ${escapeHTML(
                item.skill
              )}
            </strong>
          </td>

          <td>
            ${item.currentLevel}/5
            <br>
            <small>
              ${escapeHTML(
                item.currentLevelLabel
              )}
            </small>
          </td>

          <td>

            <div class="progress">

              <div
                class="progress-bar"
                style="width:${percentage}%"
              ></div>

            </div>

          </td>

          <td>
            ${item.score}
          </td>

          <td>

            <span
              class="badge ${getStatusClass(
                item.status
              )}"
            >

              ${escapeHTML(
                item.status
              )}

            </span>

          </td>

        </tr>

      `;

    })

    .join("");


// ============================================================
// 18. HTML - STRONG SKILLS
// ============================================================

const strongHTML =

  strongSkills.length > 0

    ? strongSkills

        .map(

          skill => `

            <span class="skill-tag">

              ${escapeHTML(
                skill
              )}

            </span>

          `

        )

        .join("")

    : `<p>No strong skills identified.</p>`;


// ============================================================
// 19. HTML - PARTIAL SKILLS
// ============================================================

const partialHTML =

  partialSkills.length > 0

    ? partialSkills

        .map(

          skill => `

            <li>

              <strong>
                ${escapeHTML(
                  skill
                )}
              </strong>

              <span>
                Needs more practical
                experience.
              </span>

            </li>

          `

        )

        .join("")

    : `<li>No major partial skills.</li>`;


// ============================================================
// 20. HTML - MISSING SKILLS
// ============================================================

const missingHTML =

  missingSkills.length > 0

    ? missingSkills

        .map(

          skill => `

            <li>

              <strong>
                ${escapeHTML(
                  skill
                )}
              </strong>

              <span>
                Important skill that
                is currently missing.
              </span>

            </li>

          `

        )

        .join("")

    : `<li>No major missing skills.</li>`;


// ============================================================
// 21. HTML - ROADMAP
// ============================================================

const roadmapSkills =
  priorityGaps.slice(
    0,
    10
  );


const roadmapHTML =

  roadmapSkills.length > 0

    ? roadmapSkills

        .map(

          (item, index) => `

            <div class="roadmap-item">

              <div class="roadmap-number">

                ${index + 1}

              </div>

              <div>

                <h4>

                  ${escapeHTML(
                    item.skill
                  )}

                </h4>

                <p>

                  ${
                    item.status ===
                    "Missing"

                      ? "Learn this skill from fundamentals and build a practical project."

                      : "Improve this skill through practical projects, coding exercises and interview preparation."
                  }

                </p>

              </div>

            </div>

          `

        )

        .join("")

    : `<p>No major learning gaps detected.</p>`;


// ============================================================
// 22. HTML REPORT
// ============================================================

const html = `

