      ${missingSkills.length}

    </div>

  </div>


</div>


<!-- =================================================
     READINESS
     ================================================= -->

<div class="section">

  <h2>
    Job Readiness
  </h2>

  <h3>

    ${escapeHTML(
      jobReadiness
    )}

  </h3>

  <p>

    ${escapeHTML(
      scoreMessage
    )}

  </p>

</div>


<!-- =================================================
     SKILL COMPARISON
     ================================================= -->

<div class="section">

  <h2>
    Skill Comparison
  </h2>

  <div class="table-wrapper">

    <table>

      <thead>

        <tr>

          <th>
            Skill
          </th>

          <th>
            Current Level
          </th>

          <th>
            Proficiency
          </th>

          <th>
            Score
          </th>

