    First 30 Days
  </h3>

  <ul>

    ${
      roadmap["30_Days"]
        .map(
          skill =>
            `<li>${escapeHTML(skill)}</li>`
        )
        .join("")
      ||
      "<li>Continue strengthening current skills.</li>"
    }

  </ul>


  <h3>
    First 60 Days
  </h3>

  <ul>

    ${
      roadmap["60_Days"]
        .map(
          skill =>
            `<li>${escapeHTML(skill)}</li>`
        )
        .join("")
      ||
      "<li>Continue practical projects.</li>"
    }

  </ul>


  <h3>
    First 90 Days
  </h3>

  <ul>

    ${
      roadmap["90_Days"]
        .map(
          skill =>
            `<li>${escapeHTML(skill)}</li>`
        )
        .join("")
      ||
      "<li>Prepare for interviews and real-world projects.</li>"
